INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f54370d6e0a3987ccd1c9d688e5cca102c2c9112/content/books/zizhi-tongjian/vol-294/year-0958/part-07/sources/library/jiuwudaishi-118-december-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002793；EPUB电子本，纸本及异文待核", "id": "e42954e0-f40a-5f9e-af16-089f11bf1c33"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f54370d6e0a3987ccd1c9d688e5cca102c2c9112/content/books/zizhi-tongjian/vol-294/year-0958/part-07/sources/library/jiuwudaishi-118-november-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002792；EPUB电子本，纸本及异文待核", "id": "25cc2391-6fd2-594b-9578-22d253790919"}, {"title": "旧五代史·卷一百二十三", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f54370d6e0a3987ccd1c9d688e5cca102c2c9112/content/books/zizhi-tongjian/vol-294/year-0958/part-07/sources/library/jiuwudaishi-123-anshenqi-conspiracy/source.txt", "note": "《旧五代史》卷一百二十三，段落 jiu-wudaishi-205deb4a7860-p002853；EPUB电子本，纸本及异文待核", "id": "b074f916-211f-5b03-bb27-4f1c5a66dd0f"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f54370d6e0a3987ccd1c9d688e5cca102c2c9112/content/books/zizhi-tongjian/vol-294/year-0958/part-07/sources/library/tongjian-294-958-959-boundary/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003491；电子底本待考，分段待核", "id": "bbb854cf-7d17-5784-a960-67ff708a4337"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f54370d6e0a3987ccd1c9d688e5cca102c2c9112/content/books/zizhi-tongjian/vol-294/year-0958/part-07/sources/library/xinwudaishi-62-chenjue-qiqiu-purge/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003156；EPUB电子本，纸本及异文待核", "id": "954aa798-b817-5f17-94fa-0554b2fb5776"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/tongjian-294-958-year-end/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003490；电子底本待考，分段待核", "id": "1bfd9414-4137-5a2f-b62c-934882fa2685"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/xinwudaishi-65-liusheng-death/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003291；EPUB电子本，纸本及异文待核", "id": "20b661b8-66cb-5f8a-9fb7-ab216028b5ff"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "窦俨", "aliases": ["竇儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "窦仪的弟弟，后周中书舍人。957年九月上疏建议编修礼乐、改善官员选拔、治盗与劝农等。《宋史》还记其治理六纲奏疏和考正雅乐经历，各条未明确的日期保留未知。生卒年未载。", "biography": null, "status": "draft", "id": "db93a2b0-a248-5d82-b836-c6c907b158ff"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李玉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周右赞善大夫。958年十月任西南面水陆制置使高防的判官，参与伐蜀准备。生卒年本段未载。", "biography": null, "status": "draft", "id": "bd3d28f8-d05f-51b4-b32c-050f2889ae8b"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "李承勋（后蜀归安镇遏使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀归安镇遏使。958年十二月据险截击后周判官李玉所率部队，杀死李玉，使其部众覆没。与早期史料中的同名人物分别保存，未发现同人证据。生卒年未载。", "biography": null, "status": "draft", "id": "380fad43-011a-5acc-8382-84618a411ba0"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵崇韬", "aliases": ["趙崇韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。955年五月，孟昶任命他为北路行营都监，参与抵御后周军的部署。生卒年未载。", "biography": null, "status": "draft", "id": "ac2d7f68-da6e-560c-8f7c-7521a8bbffce"}, {"name": "孟贻业", "aliases": ["孟貽業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀奉銮肃卫都指挥使、武信节度使兼中书令。958年十二月任昭武、文州都招讨使，参与抵御后周的部署。生卒年未载。", "biography": null, "status": "draft", "id": "e2f8bd58-26d0-583f-958c-93e76559756c"}, {"name": "赵思进", "aliases": ["趙思進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀左卫圣马军都指挥使。958年十二月任东面招讨使，参与后蜀在要地部署兵力以防后周。生卒年未载。", "biography": null, "status": "draft", "id": "575afd1d-4525-57bb-a6c3-43bc46e8cebd"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李征古", "aliases": ["李徵古"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐枢密副使。《通鉴》记956年参与指控李德明卖国，后来在常州救援部署中给柴克宏朽损装备、召其回朝并拟用朱匡业替代。指控与能力评价保留来源立场，不认作李德明确实卖国。", "biography": null, "status": "draft", "id": "4166fee2-b566-55ec-8218-943eafdc5242"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "陈乔", "aliases": ["陳喬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "豫章人，南唐中书舍人。李璟一度命他起草委国事于宋齐丘的诏书，他请求面见并力言不可，李璟停止这一安排。该事为追述，确切年月未载，生卒年未核。", "biography": null, "status": "draft", "id": "d1fec795-08d6-56f2-8897-4df3f38c7262"}, {"name": "严续", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：严续。", "biography": null, "status": "draft", "id": "57b5cb9f-cb31-5e6a-87de-6363e1836468"}, {"name": "殷崇义", "aliases": ["殷崇義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员。955年后周兵将至，李璟由翰林承旨、户部尚书任其为吏部尚书、知枢密院。生卒年及其他别名待对应史料补核。", "biography": null, "status": "draft", "id": "929f5ee1-ebb3-556e-b4ac-aa35cf7619a6"}, {"name": "高彦俦", "aliases": ["高彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高彦俦，太原人、昭武都监、拟领兵者。", "biography": null, "status": "draft", "id": "b335c31e-ee43-595d-8eb5-e601824ba527"}, {"name": "安友进", "aliases": ["安友進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦的仆人。与安审琦受宠的妾私通，受到告发威胁后同意谋杀安审琦。谋划记于958年末，实施在959年正月，二者分别录入。生卒年本段未载。", "biography": null, "status": "draft", "id": "2a4711e7-4ef4-595e-8398-f348d7b750da"}, {"name": "安审琦妾（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦受宠的妾，姓名未载。与仆人安友进私通，因怕事情泄露而提出谋杀安审琦，并威胁向安审琦告发安友进。谋划的具体日期未载。", "biography": null, "status": "draft", "id": "c75ec8f6-6b1b-5a07-8dd3-5923d6759435"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

